def transform(grid):
    n = len(grid)
    m = len(grid[0])
    out = [[7] * m for _ in range(n)]
    seen = set()
    for r in range(n):
        for c in range(m):
            if grid[r][c] == 7 or (r, c) in seen:
                continue
            color = grid[r][c]
            cells = []
            stack = [(r, c)]
            seen.add((r, c))
            while stack:
                x, y = stack.pop()
                cells.append((x, y))
                for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    a, b = x + dx, y + dy
                    if 0 <= a < n and 0 <= b < m and (a, b) not in seen and grid[a][b] == color:
                        seen.add((a, b))
                        stack.append((a, b))
            r0 = min(x for x, y in cells)
            r1 = max(x for x, y in cells)
            c0 = min(y for x, y in cells)
            c1 = max(y for x, y in cells)
            if r0 == r1 and c0 == c1:
                for x in range(max(0, r0 - 4), min(n, r0 + 5)):
                    for y in range(max(0, c0 - 4), min(m, c0 + 5)):
                        out[x][y] = color
            else:
                for x in range(r0 + 1, r1):
                    for y in range(c0 + 1, c1):
                        out[x][y] = color
    return out
